entries[1217880] = { ["name"] = "Bevorstehender Sieg", ["text"] = "Nahkampfreichweite\nSofort\nGreift das Ziel sofort an, verursacht 1 Schaden und heilt Euch um 30% Eurer maximalen Gesundheit.\n\nNach dem Töten eines Gegners, der Erfahrung oder Ehre gewährt, wird die Abklingzeit von 'Bevorstehender Sieg' abgeschlossen und die Fähigkeit kostet keine Wut." }
entries[1217884] = { ["name"] = "Explosion", ["text"] = "100 Meter Reichweite\nSofort\nDer Zaubernde gräbt sich in die Erde ein und bricht an einem Ort in der Nähe aus, fügt Spielercharakteren innerhalb von 8 Metern um den Ausbruchsbereich 75 körperlichen Schaden zu und schleudert sie nach oben.\n\nFügt allen anderen Spielercharakteren zusätzlich 25 körperlichen Schaden zu." }
