entries[1217891] = { ["name"] = "Experimenteller Goblin-Treibstoffzuschlag", ["text"] = "Sofort 5 min Abklingzeit\nVerringert die maximale Gesundheit um 50% und verleiht einen zufälligen Kampfbonus.\n\nKann nur in Lorenhall eingesetzt werden. Gegner lassen zusätzliche Marktforschung für den Zaubernden fallen, während dieser Effekt aktiv ist." }
