entries[1218090] = { ["name"] = "Urzeitlicher Sturm", ["text"] = "0.8% von Grundmana Nahkampfreichweite\nSofort\nVerwüstet Gegner in der Nähe mit 'Urzeitlicher Sturm', der (90% der Angriffskraft) Flammenschlag-, (90% der Angriffskraft) Frostschlag-, und (90% der Angriffskraft) Sturmschlagschaden verursacht und einen 'Blitzschlag' oder 'Kettenblitzschlag' mit 100% Effektivität entfesselt. Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu.\n\nVerbraucht 'Waffe des Mahlstroms', um mehr Schaden zu verursachen." }
