entries[1218103] = { ["name"] = "Augenstrahl", ["text"] = "Unbegrenzte Reichweite\nWirken in 2 sek.\nVelaryn kanalisiert 4 Sek. lang einen Strom aus Teufelsenergie auf ihr aktuelles Ziel, fügt Spielercharakteren innerhalb des Strahls alle (1 / 2) Sek. 5621532 Chaosschaden zu, belegt sie mit ' Teufelsversengt ' und schleudert sie zurück.\n\nNach dem Angriff setzt Velaryn ' Teufelsklinge ' gegen ihr aktuelles Ziel ein." }
