entries[1218301] = { ["name"] = "Autobewerberprototyp", ["text"] = "8 Meter Reichweite\nSofort 5 min Abklingzeit\nPlatziert den Autobewerber, der alle Kreaturen in der Nähe extrem anwidert, wodurch sie Euch 3 Min. lang 50% mehr Schaden zufügen.\n\nKann nur in Lorenhall eingesetzt werden. Gegner lassen zusätzliche Marktforschung für den Zaubernden fallen, während dieser Effekt aktiv ist." }
