entries[1218305] = { ["name"] = "Leerengeschmiedeter Hengst", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Geschmiedet wie einst die Eisen an ihren Hufen, handelt es sich bei diesen Kreaturen nun weniger um Pferde sondern mehr um Leerenenergie in ihrer Gestalt.\"\nBeute:\nZone:\nVision von Sturmwind (Neuerlebt)" }
entries[1218306] = { ["name"] = "Leerenvernarbte Rudelmutter", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Im Kampf gegen ihre verdorbenen Halter konnte diese Rudelmutter sich und ihre Welpen befreien. Doch Freiheit von ihren Haltern bedeutete noch lange keine Freiheit von der Leere dieses verlorenen Ortes. Sie brachte ihren Welpen bei, zu noch gefährlicheren Bestien zu werden. Nun durchstreifen sie Orgrimmar auf der Suche nach Futter, während alle ums Überleben kämpfen.\"\nBeute:\nZone:\nVision von Orgrimmar (Neuerlebt)" }
entries[1218307] = { ["name"] = "Leerenvernarbter Windreiter", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Als die Leerenenergien entfesselt wurden, verfielen die meisten Windreiter in Raserei, wobei sie sich gegenseitig und ihre Ausbilder töteten. Die Tore zu ihrem Horst wurden von den Überlebenden verschlossen. Oben kann man noch einige der überlebenden Windreiter gleiten sehen, doch niemand traut sich, in ihr neues, tödliches Zuhause zurückzukehren, um zu sehen, was davon übrig ist.\"\nBeute:\nZone:\nVision von Orgrimmar (Neuerlebt)" }
entries[1218308] = { ["name"] = "Entzündendes Inferno", ["text"] = "Sofort\nLohenzar entfesselt eine feurige Explosion auf jede gelöschte Kerze, entzündet sie wieder und fügt allen dabei getroffenen Spielercharakteren 8487876 Feuerschaden zu.\n\nDas Inferno versengt alle Spielercharaktere und fügt ihnen so 8 Sek. lang alle 1 Sek. 242445 Feuerschaden zu. Dieser Effekt ist stapelbar." }
entries[1218310] = { ["name"] = "Elektropunkturtestmodell", ["text"] = "30 Meter ReichweiteWirken in 2 sek. 10 min Abklingzeit\nDas Ziel wird von belebender Spannung durchströmt, was 3 Min. lang sein Tempo um 20% erhöht, den erlittenen Schaden um 25% verringert und es Naturschaden pulsieren lässt.\n\nKann bei den meisten seltenen Kreaturen in Lorenhall eingesetzt werden. Ziele lassen zusätzliche Marktforschung für alle Spielercharaktere fallen, während dieser Effekt aktiv ist." }
entries[1218311] = { ["name"] = "Noggenfoggers Frischeauslese", ["text"] = "Sofort 0.5 sek. Abklingzeit\nWird vorübergehend kalt." }
entries[1218313] = { ["name"] = "Erhellen" }
entries[1218314] = { ["name"] = "Ny'alothischer Schattenwurm", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren ny'alothischen Schattenwurm oder gibt ihn wieder frei.\n\"Als Überrest der Vergangenheit des Schwarzen Imperiums kehren diese Vorläufer der Kluftwürmer mit dem Aufstieg von Ny'alotha wieder zurück.\"\nErfolg:\nMeister der VisionenKategorie:\nNeuerlebte Visionen von N'Zoth" }
entries[1218315] = { ["name"] = "Elektropunkturtestmodell", ["text"] = "20 Meter Reichweite\nSofort\nVerursacht 7 Naturschaden." }
entries[1218316] = { ["name"] = "Verderbnis der Aspekte", ["text"] = "Wirken in 1.5 sek.\nBeschwört die Verderbnis der Aspekte oder gibt sie wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n\"Mit N'Zoths Triumph wird das, was mit Galakrond begann, endlich Wirklichkeit. Und mit dem Verschwinden der Aspekte ist das Verderben ihrer Spezies vollbracht.\"\nVerkäufer:\nTorie\nZone:\nDornogal\nKosten:\n40.000" }
entries[1218317] = { ["name"] = "Leerenkristallpanther", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren Leerenkristallpanther oder gibt ihn wieder frei.\n\"Obwohl viele kostbare Edelsteine in verstörenden Visionen von den Leerenenergien verderbt wurden, können Juwelierskunstmeister sie immer noch verwenden, um mächtige Pantherrösser herzustellen.\"\nBeruf:\nJuwelierskunst" }
