entries[1218439] = { ["name"] = "Siegesserie!", ["text"] = "Sofort\nEure Zauber und Fähigkeiten haben eine Chance, eine Siegesserie! zu aktivieren, die den Schaden von 'Vergiften', 'Blutung' und 'Blutroter Sturm' um 3% erhöht und bis zu 10-mal stapelbar ist. 'Vergiften', 'Blutung' und 'Blutroter Sturm' haben eine Chance von 15%, Eure Siegesserie! zu entfernen.\n(Procchance: 15%, 100ms Abklingzeit)" }
