entries[1218488] = { ["name"] = "Streubombenkanister", ["text"] = "Unbegrenzte Reichweite\nWirken in 3.5 sek.\nGallywix trifft sein aktuelles Ziel und fügt ihm 16770174 körperlichen Schaden zu. Dieser Angriff kann nicht pariert und ihm kann nicht ausgewichen werden.\n\nÜberzieht zusätzlich Spielercharaktere in einem frontalen kegelförmigen Bereich mit 41925435 Feuerschaden und erhöht den durch 'Streubombenkanister' erlittenen Schaden 1.1 Min. lang um 400%. Der Schaden teilt sich gleichmäßig auf betroffene Spielercharaktere auf und strahlt dann auf andere Spielercharaktere innerhalb von 5Metern aus.\n\nDies erzeugt ' Kanister des Mechmeisteringenieurs ', wodurch alle betroffenen Spielercharaktere miteinander verbunden werden.\n\nWenn nicht mindestens 5 Ziele getroffen werden, erleiden alle Spielercharaktere den vollen Effekt." }
entries[1218489] = { ["name"] = "Streubombenkanister", ["text"] = "Unbegrenzte Reichweite\nSofort\nGallywix trifft sein aktuelles Ziel und fügt ihm 16770174 körperlichen Schaden zu. Dieser Angriff kann nicht pariert und ihm kann nicht ausgewichen werden.\n\nÜberzieht zusätzlich Spielercharaktere in einem frontalen kegelförmigen Bereich mit 41925435 Feuerschaden und erhöht den durch 'Streubombenkanister' erlittenen Schaden 1.1 Min. lang um 400%. Der Schaden teilt sich gleichmäßig auf betroffene Spielercharaktere auf und strahlt dann auf andere Spielercharaktere innerhalb von 5Metern aus.\n\nDies erzeugt ' Kanister des Mechmeisteringenieurs ', wodurch alle betroffenen Spielercharaktere miteinander verbunden werden.\n\nWenn nicht mindestens 5 Ziele getroffen werden, erleiden alle Spielercharaktere den vollen Effekt." }
entries[1218490] = { ["name"] = "Streubombenkanister", ["text"] = "Unbegrenzte Reichweite\nSofort\nGallywix trifft sein aktuelles Ziel und fügt ihm 16770174 körperlichen Schaden zu. Dieser Angriff kann nicht pariert und ihm kann nicht ausgewichen werden.\n\nÜberzieht zusätzlich Spielercharaktere in einem frontalen kegelförmigen Bereich mit 41925435 Feuerschaden und erhöht den durch 'Streubombenkanister' erlittenen Schaden 1.1 Min. lang um 400%. Der Schaden teilt sich gleichmäßig auf betroffene Spielercharaktere auf und strahlt dann auf andere Spielercharaktere innerhalb von 5Metern aus.\n\nDies erzeugt ' Kanister des Mechmeisteringenieurs ', wodurch alle betroffenen Spielercharaktere miteinander verbunden werden.\n\nWenn nicht mindestens 5 Ziele getroffen werden, erleiden alle Spielercharaktere den vollen Effekt." }
entries[1218491] = { ["name"] = "Streubombenkanister", ["text"] = "Unbegrenzte Reichweite\nSofort\nGallywix trifft sein aktuelles Ziel und fügt ihm 20950056 körperlichen Schaden zu. Dieser Angriff kann nicht pariert und ihm kann nicht ausgewichen werden.\n\nZusätzlich werden Spielercharaktere in einem frontalen kegelförmigen Bereich angegriffen, die 46083683 Feuerschaden erleiden. Durch 'Streuschlagkanister' erlittener Schaden ist lang um 100% erhöht. Der Schaden teilt sich gleichmäßig auf betroffene Spielercharaktere auf.\n\nAlle Ziele werden mit ' Kanister des Mechingenieurs ' belegt.\n\nWenn die Detonation nicht mindestens 3 Ziele trifft, erleiden alle Spielercharaktere den vollen Effekt." }
entries[1218492] = { ["name"] = "Streubombenkanister", ["text"] = "Unbegrenzte Reichweite\nSofort\nGallywix trifft sein aktuelles Ziel und fügt ihm 16770174 körperlichen Schaden zu. Dieser Angriff kann nicht pariert und ihm kann nicht ausgewichen werden.\n\nÜberzieht zusätzlich Spielercharaktere in einem frontalen kegelförmigen Bereich mit 41925435 Feuerschaden und erhöht den durch 'Streubombenkanister' erlittenen Schaden 1.1 Min. lang um 400%. Der Schaden teilt sich gleichmäßig auf betroffene Spielercharaktere auf und strahlt dann auf andere Spielercharaktere innerhalb von 5Metern aus.\n\nDies erzeugt ' Kanister des Mechmeisteringenieurs ', wodurch alle betroffenen Spielercharaktere miteinander verbunden werden.\n\nWenn nicht mindestens 5 Ziele getroffen werden, erleiden alle Spielercharaktere den vollen Effekt." }
entries[1218493] = { ["name"] = "Streubombenkanister", ["text"] = "Unbegrenzte Reichweite\nSofort\nGallywix trifft sein aktuelles Ziel und fügt ihm 200 körperlichen Schaden zu. Dieser Angriff kann nicht pariert und ihm kann nicht ausgewichen werden.\n\nÜberzieht zusätzlich Spielercharaktere in einem frontalen kegelförmigen Bereich mit 500 Feuerschaden und erhöht den durch 'Streubombenkanister' erlittenen Schaden 1.1 Min. lang um 400 %. Der Schaden teilt sich gleichmäßig auf betroffene Spielercharaktere auf und strahlt dann auf andere Spielercharaktere innerhalb von 5Metern aus.\n\nDies erzeugt ' Kanister des Mechmeisteringenieurs ', wodurch alle betroffenen Spielercharaktere miteinander verbunden werden.\n\nWenn nicht mindestens 5 Ziele getroffen werden, erleiden alle Spielercharaktere den vollen Effekt." }
