entries[1218694] = { ["name"] = "Resonante Echos", ["text"] = "Wirken in 0.25 sek.\nEine widerhallende Schallwelle überwältigt Spielercharaktere in ihrer Bahn und verursacht 6 Sek. lang alle 0.5 Sek. 670807 Schallschaden. Dieser Effekt ist stapelbar." }
entries[1218696] = { ["name"] = "Raketen des Durcheinanders", ["text"] = "Unbegrenzte Reichweite\nWirken in 5 sek.\nGallywix wurde herauskatapultiert, ist aber immer noch gefährlich. Er erfasst Ziele und lässt 1 Sek. lang Raketen herabregnen, die Spielercharakteren innerhalb von 8 Metern um einen Einschlag 12577631 Feuerschaden zufügen." }
entries[1218698] = { ["name"] = "Blutsteine" }
entries[1218702] = { ["name"] = "Blutstein erschaffen" }
entries[1218703] = { ["name"] = "Werkstatt des Chaos", ["text"] = "Unbegrenzte Reichweite\nSofort\nIm Haus des Chroms brennt etwas durch und der Strom verursacht bei Berührung alle 1 Sek. 8385087 Naturschaden." }
entries[1218704] = { ["name"] = "Stromspulenprototyp", ["text"] = "300 Meter Reichweite\nKanalisiert (Wirken in 10 sek.)\nExperimentelle Stromspulen tauchen aus der Deponie auf.\n\nStromspulen verbinden sich mit einem zufälligen Spielercharakter und entladen ihre gespeicherte Energie, was diesem 293478 Naturschaden zufügt und ihn 10 Sek. lang alle 0.5 Sek. mit 1 Stapel von ' Hypergeladen ' belegt." }
entries[1218706] = { ["name"] = "Stromspulenprototyp", ["text"] = "Unbegrenzte Reichweite\nSofort\nExperimentelle Stromspulen tauchen aus der Deponie auf.\n\nStromspulen verbinden sich mit einem zufälligen Spielercharakter und entladen ihre gespeicherte Energie, was diesem 293478 Naturschaden zufügt und ihn 10 Sek. lang alle 0.5 Sek. mit 1 Stapel von ' Hypergeladen ' belegt." }
entries[1218708] = { ["name"] = "Hypergeladen", ["text"] = "Unbegrenzte Reichweite\nSofort\nÜberschüssige Ladung staut sich im Körper des Ziels und erhöht seinen durch 'Stromspulenprototyp' erlittenen Schaden um 30% pro Stapel." }
entries[1218710] = { ["name"] = "Teleport nach Dornogal", ["text"] = "Unbegrenzte Reichweite\nSofort\nTeleportiert den Zauberwirker nach Dornogal." }
entries[1218712] = { ["name"] = "Explosion nach Explosion" }
entries[1218713] = { ["name"] = "Explosives Adrenalin", ["text"] = "Sofort\nFunktioniert eine Zephyriumladung um und treibt Eure Herzfrequenz nach oben, wodurch Eure erste Fähigkeit alle 60 Sek. 'Explosives Adrenalin' auslöst, was 15 Sek. lang Euren kritischen Trefferwert um 105 erhöht.\n\nWährend der Explosion bewirken kritische Treffer, dass Ihr erneut explodiert, wodurch sich die Dauer bis zu 15-mal um 1 Sek. verlängert." }
entries[1218714] = { ["name"] = "Improvisierter Zephyriumschrittmacher", ["text"] = "Funktioniert eine Zephyriumladung um und treibt Eure Herzfrequenz nach oben, wodurch Eure erste Fähigkeit alle 60 Sek. 'Explosives Adrenalin' auslöst, was 15 Sek. lang Euren kritischen Trefferwert um 105 erhöht.\n\nWährend der Explosion bewirken kritische Treffer, dass Ihr erneut explodiert, wodurch sich die Dauer bis zu 15-mal um 1 Sek. verlängert." }
entries[1218715] = { ["name"] = "Kurze Explosionspause", ["text"] = "Sofort\nFunktioniert eine Zephyriumladung um und treibt Eure Herzfrequenz nach oben, wodurch Eure erste Fähigkeit alle 60 Sek. 'Explosives Adrenalin' auslöst, was 15 Sek. lang Euren kritischen Trefferwert um 105 erhöht.\n\nWährend der Explosion bewirken kritische Treffer, dass Ihr erneut explodiert, wodurch sich die Dauer bis zu 15-mal um 1 Sek. verlängert." }
entries[1218716] = { ["name"] = "K.U.-J.O.s Flammendüsen", ["text"] = "Kanalisiert (Wirken in 2 sek.) 2 min Abklingzeit\nKanalisiert, um 2 Sek. lang Flammen auszustoßen, die [Quellwert] Feuerschaden verursachen, die auf Gegner in der Nähe aufgeteilt werden.\n\nMechanische Gegner werden 'Supererhitzt', wodurch sie 281 zusätzlichen Feuerschaden erleiden, wenn sie von Eurer nächsten Schadensfähigkeit getroffen werden.", ["unresolvedValues"] = true }
entries[1218717] = { ["name"] = "Ablassen", ["text"] = "Sofort\nKanalisiert, um 2 Sek. lang Flammen auszustoßen, die ( 1973 * 3) Feuerschaden verursachen, die auf Gegner in der Nähe aufgeteilt werden.\n\nMechanische Gegner werden 'Supererhitzt', wodurch sie 281 zusätzlichen Feuerschaden erleiden, wenn sie von Eurer nächsten Schadensfähigkeit getroffen werden." }
