entries[1219102] = { ["name"] = "Schlammgetragen", ["text"] = "Sofort 2 min Abklingzeit\nWerdet 'Schlammgetragen', wodurch Ihr 33535 Schaden absorbiert und im Verlauf von 10 Sek. regelmäßig ( 331 * 10 / 2) Naturschaden verursacht, der zwischen Gegnern in der Nähe aufgeteilt wird.\n\nWenn Ihr regelmäßigen Schaden erleidet, verschmilzt dieser zu stinkendem Schlamm, der das Ritual weiter nährt und die Abklingzeit um [2][2.0] Sek. verringert." }
entries[1219103] = { ["name"] = "Gigaschocks Schockkappe", ["text"] = "Alle 6 Sek. versetzt Ihr Eurem Ziel und 1 Gegner in der Nähe einen Schock und fügt ihnen ( 107 * 1 ) Naturschaden zu.\n\nDurch den Einsatz von 30 Zaubern werdet Ihr für 15 Sek. 'Turbogeladen', was die Häufigkeit Eurer Schocks verdoppelt und sie zu Gigaschocks macht, die stattdessen ( 107 * 3 * 1 ) Naturschaden verursachen.\n(500ms Abklingzeit)" }
