entries[1219245] = { ["name"] = "Flammen des Ruhms", ["text"] = "Sofort\nDer Spielercharakter übernimmt die Kontrolle eines zurückgelassenen Gangzwingermotorrads und lässt es in ' Flammen des Ruhms ' nach vorne rasen.\n\nWenn das Motorrad den Gangzwinger trifft, erleidet der Kriegspanzer 1% seiner maximalen Gesundheit als Schaden und verliert 1 Stapel von ' Schutzpanzerung ', während das Motorrad explodiert, was allen Spielercharakteren 838509 Feuerschaden zufügt und ' Brennendes Schrapnell ' mehrmals auslöst." }
