entries[1219253] = { ["name"] = "Emporstoßen", ["text"] = "100 Meter Reichweite\nSofort\nSammelt irdene Macht unter den Füßen Eures Gegners und schleudert ihn nach oben, was dem Ziel sowie Gegnern in der Nähe (430% der Zaubermacht) Vulkanschaden zufügt. [ Sande der Zeit : Erhöht die Dauer Eurer aktiven Effekte von 'Schwarzmacht' um 2 Sek ]\nDurch Ermächtigung vergrößert sich der Effektbereich.\n\nI: Radius von 3 Metern.\n\nII: Radius von 6 Metern.\n\nIII: Radius von 9 Metern." }
