entries[1219263] = { ["name"] = "Arkanokanone der Auslöschung", ["text"] = "300 Meter Reichweite\nWirken in 6 sek.\nDie Plexuswache markiert ihr aktuelles Ziel und verschießt dann eine arkane Ladung, die allen Spielercharakteren innerhalb von 10 Metern 26702279 Arkanschaden sowie allen anderen Spielercharakteren 25296896 Arkanschaden zufügt. Weiter vom Ziel entfernte Spielercharaktere erleiden weniger Schaden. Die Explosion hinterlässt ' Potente Manarückstände '.\n\nDer Einschlag fügt dem Primärziel 45 Sek. lang 1000% Schaden durch ' Arkanokanone der Auslöschung ' zu." }
entries[1219264] = { ["name"] = "Auszahlung!", ["text"] = "Sofort\nWenn Eure Siegesserie! enden würde, habt Ihr stattdessen eine Chance, für 4 Sek. die maximalen Stapel von Siegesserie! zu erhalten. Diese Stapel können nicht entfernt werden und ihr Effekt ist 50% stärker, solange sie immun gegen Entfernung sind." }
