entries[1219278] = { ["name"] = "Gallykies-Schädlingsvernichter", ["text"] = "Unbegrenzte Reichweite\nSofort\nHumaner Hochspannungsschock. Schaltet Schädlinge schnell aus. Gallywix befestigt Blitzketten an anvisierten Spielercharakteren, die diesen sowie allen anderen Spielercharakteren zwischen ihnen und Gallywix alle 0.5 Sek. 503105 Naturschaden zufügen. Der Schaden dieses Effekts erhöht sich, wenn die angeketteten Ziele sich weiter von Gallywix entfernt befinden." }
